		        // remove an ending ".ip6.arpa", with or without the root dot
		        const nibbles = arpaFormAddress.replace(/(\.ip6\.arpa)?\.?$/, '');
		        if (!/^[0-9a-f](\.[0-9a-f]){0,31}$/i.test(nibbles)) {
		            throw new address_error_1.AddressError("Invalid 'ip6.arpa' form.");
		        }
